import scipy.io as sio, numpy as np
h=sio.loadmat('swa-spectrum.fig',squeeze_me=True,struct_as_record=False)
def dump(x,d=0,maxd=6,name='root'):
    if d>maxd: return
    if hasattr(x,'_fieldnames'):
        print('  '*d+name+': struct fields='+str(x._fieldnames)[:200])
        for f in x._fieldnames:
            dump(getattr(x,f),d+1,maxd,f)
    elif isinstance(x,np.ndarray) and x.dtype==object:
        print('  '*d+name+': objarray shape='+str(x.shape))
        for i in range(min(x.size,4)):
            dump(x.flat[i],d+1,maxd,f'[{i}]')
    else:
        s=str(x)
        print('  '*d+name+': '+type(x).__name__+' '+s[:80])
dump(h['hgS_080000'],0,4,'hgS')
EOF"}

